where idprg = #{applicativo} and idcom = #{id}

mapper.insert:
insert into w_docdig (idprg, iddocdig, digent, digkey1, digkey2, digkey3, digkey4, digtipdoc, dignomdoc, digdesdoc, digogg, firmacheck, firmacheckts, bucket_uuid, bucket_ref)
values (
    #{applicativo}
    , #{id}
    , #{entita}
    , #{idComunicazione}
    , #{progressivo}
    , #{uuid,jdbcType=VARCHAR}
    , #{cifrato,jdbcType=VARCHAR}
    , #{tipo,jdbcType=VARCHAR}
    , #{nomeFile,jdbcType=VARCHAR}
    , #{descrizione,jdbcType=VARCHAR}
    , #{file,jdbcType=BINARY}
    , #{firmacheck,jdbcType=VARCHAR}
    , #{firmacheckts,jdbcType=TIMESTAMP}
    , #{bucket_info.uuid}
    , #{bucket_info.bucket_ref}
)

update w_docdig set digkey2 = #{progressivo}, digtipdoc = #{tipo,jdbcType=VARCHAR}, dignomdoc = #{nomeFile,jdbcType=VARCHAR}, digdesdoc = #{descrizione,jdbcType=VARCHAR},
					   digogg = #{file,jdbcType=BINARY}, 
                       digogg = NULL, 
                    digkey3 = #{uuid,jdbcType=VARCHAR},
                    digkey4 = #{cifrato,jdbcType=VARCHAR}
                     , firmacheck = #{firmacheck,jdbcType=VARCHAR} 
                     , firmacheckts = #{firmacheckts,jdbcType=TIMESTAMP} 
                      , bucket_ref = #{info.bucket_ref,jdbcType=VARCHAR}
                      , bucket_uuid = #{info.uuid,jdbcType=VARCHAR}
where idprg = #{applicativo} and iddocdig = #{id} and digent = #{entita} and digkey1 = cast(#{idComunicazione} as varchar(30))

